        const storagePackage = { isLocked: isDayLocked, data: rekapData };
        localStorage.setItem(`rekap_finance_${selectedDate}`, JSON.stringify(storagePackage));
        
        if (rekapData.modalUtama > 0) localStorage.setItem(`rekap_finance_modal_global`, rekapData.modalUtama.toString());
