import { 
    initializeApp 
} from "firebase/app";
import { 
    getFirestore, 
    doc, 
    setDoc, 
    serverTimestamp, 
    collection, 
    query,      
    getDocs,    
    orderBy,    
    deleteDoc, 
    updateDoc  
} from "firebase/firestore";

// --- KONFIGURASI FIREBASE ---
const FIREBASE_CONFIG = {
  apiKey: process.env.REACT_APP_FIREBASE_KEY, 
  authDomain: process.env.REACT_APP_FIREBASE_DOMAIN || "vdvoucher.firebaseapp.com",
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID || "vdvoucher", 
  storageBucket: process.env.REACT_APP_FIREBASE_STORAGE || "vdvoucher.firebasestorage.app",
  messagingSenderId: process.env.REACT_APP_FIREBASE_SENDER || "535315980318",
  appId: process.env.REACT_APP_FIREBASE_APP_ID || "1:535315980318:web:ac71d91380d51f1a7ace0f"
};

const DB_COLLECTION_NAME = 'extracted_vouchers'; 
const REKAPAN_COLLECTION = 'rekapan_operasional'; // Koleksi baru untuk Rekapan.js

// --- CONSTANTS ---
// Menambahkan variabel webhook sesuai instruksi memori Anda
export const WEBHOOK_ID = process.env.REACT_APP_WEBHOOK_ID || "WEBHOOK_v7_ASSET_DETAIL_CLICKABLE"; 

// --- INISIALISASI FIREBASE ---
const app = initializeApp(FIREBASE_CONFIG);
export const db = getFirestore(app);

/**
 * FUNGSI KHUSUS UNTUK REKAPAN.JS
 * Menyimpan data operasional harian ke Firestore
 */
export async function saveRekapData(date, data, showStatus) {
    try {
        const docRef = doc(db, REKAPAN_COLLECTION, date);
        await setDoc(docRef, {
            ...data,
            lastUpdated: serverTimestamp()
        }, { merge: true });
        
        if (showStatus) showStatus("Data tersinkronisasi ke Cloud", "success");
        return { success: true };
    } catch (err) {
        console.error("Error saving rekap data: ", err);
        if (showStatus) showStatus(`Gagal sinkron: ${err.message}`, 'error');
        throw err;
    }
}

/**
 * Menyimpan kode voucher yang diekstrak (Fungsi Lama)
 */
export async function saveCodesToDatabase(codes, filename, showStatus) {
    try {
        const docId = `extraction_${Date.now()}`;
        const docRef = doc(db, DB_COLLECTION_NAME, docId);

        await setDoc(docRef, {
            codes: codes,
            filename: filename,
            timestamp: serverTimestamp(),
            count: codes.length,
            webhookId: WEBHOOK_ID // Menyertakan webhook ID
        });

        return { success: true, id: docId };
    } catch (err) {
        console.error("Error saving to Firestore: ", err);
        showStatus(`Gagal menyimpan ke database: ${err.message}`, 'error');
        throw err;
    }
}

/**
 * Mengambil riwayat ekstraksi voucher (Fungsi Lama)
 */
export async function fetchHistory(showStatus) {
    try {
        const q = query(collection(db, DB_COLLECTION_NAME), orderBy("timestamp", "desc"));
        const querySnapshot = await getDocs(q);
        
        const fetchedData = [];
        querySnapshot.forEach((doc) => {
            const data = doc.data();
            const filename = data.filename || `extracted_vouchers_${doc.id}`;
            fetchedData.push({ id: doc.id, ...data, filename: filename });
        });
        
        return fetchedData;
    } catch (err) {
        console.error("Error fetching history: ", err);
        showStatus(`Gagal memuat riwayat: ${err.message}`, 'error');
        throw err;
    }
}

/**
 * Memperbarui nama file untuk item riwayat (Fungsi Lama)
 */
export async function updateFilename(itemId, newFilename, showStatus) {
    try {
        const docRef = doc(db, DB_COLLECTION_NAME, itemId);
        await updateDoc(docRef, {
            filename: newFilename.trim()
        });
        return { success: true };
    } catch (err) {
        console.error("Error renaming document: ", err);
        showStatus(`Gagal memperbarui nama file: ${err.message}`, 'error');
        throw err;
    }
}

/**
 * Menghapus item riwayat (Fungsi Lama)
 */
export async function deleteHistoryItem(itemId, filename, showStatus) {
    try {
        await deleteDoc(doc(db, DB_COLLECTION_NAME, itemId));
        return { success: true };
    } catch (err) {
        console.error("Error deleting document: ", err);
        showStatus(`Gagal menghapus data: ${err.message}`, 'error');
        throw err;
    }
}